#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    vector<int> np;
    for (int i = n - y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n - y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    for(int k=0; k<n-2; k++){
        int pos = -1;
        for(int i=k;i<n;i++) if(p[i]==k+1){pos=i;break;}
        if(pos==k) continue;

        // We want to move element from pos to k
        // If pos > k and we can do it in one op:
        // x=pos-k, y=n-pos. x+y = n-k. Need n-k < n, true since k>0... but k could be 0
        if(k > 0) {
            int x = pos - k, y = n - pos;
            // x>0 since pos>k, y>0 since pos<n, x+y=n-k<n since k>0
            ops.push_back({x, y});
            apply(p, x, y);
        } else {
            // k=0: need element at pos to go to 0
            // Use x=1, y=n-pos if pos>1 (x+y=n-pos+1<n iff pos>1)
            if(pos > 1) {
                int x=1, y=n-pos;
                ops.push_back({x,y});
                apply(p,x,y);
                // element now at position 0? No: suffix=[pos..n-1] goes to front, element at pos goes to position 0. Yes!
            } else { // pos==1
                int x=1, y=n-2; // x+y=n-1<n
                ops.push_back({x,y});
                apply(p,x,y);
                // element was at pos=1, now in middle. Find again.
                for(int i=0;i<n;i++) if(p[i]==1){pos=i;break;}
                if(pos!=0){
                    int xx=1,yy=n-pos;
                    if(xx+yy<n && xx>0 && yy>0){
                        ops.push_back({xx,yy});
                        apply(p,xx,yy);
                    }
                }
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
